from __future__ import annotations

from exo import *
from exo.libs.memories import DRAM
from exo.API_scheduling import *

# Tunable spatial tile sizes for the interior domain.
# These are chosen to keep each TI×TJ tile (for both A and B) in cache.
TI = 32
TJ = 32


@proc
def kernel_jacobi_2d(
    tsteps: size,
    n: size,
    A: DATA_TYPE[n, n] @ DRAM,
    B: DATA_TYPE[n, n] @ DRAM,
):
    # We update only interior points [1 : n-1), so n must be > 2.
    assert n > 2

    # Hoist the Jacobi weight into a scalar so that it can live in a register.
    w: DATA_TYPE
    w = 0.2

    # Time-stepping loop. Each iteration performs:
    #   1) B <- stencil(A)
    #   2) A <- stencil(B)
    for t in seq(0, tsteps):

        # --------------------------------------------------------------
        # Phase 1: update B from A using a 5-point stencil.
        #
        # The interior [1, n-1) × [1, n-1) region is conceptually of
        # size (n-2) × (n-2). We block this interior into tiles of
        # size TI × TJ. The outer loops (II, JJ) enumerate tiles, and
        # the inner loops (i_inner, j_inner) enumerate points within
        # each tile. Conditional guards handle partial tiles at the
        # high end when (n-2) is not a multiple of TI or TJ.
        # --------------------------------------------------------------
        for II in seq(0, (n - 2 + TI - 1) // TI):
            for JJ in seq(0, (n - 2 + TJ - 1) // TJ):
                for i_inner in seq(0, TI):
                    # Convert the tile-local row index back to the
                    # global interior index (0-based interior index).
                    if II * TI + i_inner < n - 2:
                        for j_inner in seq(0, TJ):
                            # Similarly for the column.
                            if JJ * TJ + j_inner < n - 2:
                                # Global interior coordinates:
                                #   i = 1 + (II * TI + i_inner)
                                #   j = 1 + (JJ * TJ + j_inner)
                                B[
                                    1 + II * TI + i_inner,
                                    1 + JJ * TJ + j_inner,
                                ] = w * (
                                    A[1 + II * TI + i_inner, 1 + JJ * TJ + j_inner]
                                    + A[1 + II * TI + i_inner, 1 + JJ * TJ + j_inner - 1]
                                    + A[1 + II * TI + i_inner, 1 + JJ * TJ + j_inner + 1]
                                    + A[1 + II * TI + i_inner + 1, 1 + JJ * TJ + j_inner]
                                    + A[1 + II * TI + i_inner - 1, 1 + JJ * TJ + j_inner]
                                )

        # --------------------------------------------------------------
        # Phase 2: update A from B using the same stencil.
        #
        # The tiling structure exactly matches Phase 1, so we visit the
        # same interior points in a different (cache-friendly) order.
        # Boundaries A[0, *], A[n-1, *], A[*, 0], A[*, n-1] are never
        # written and therefore stay at their initialized values.
        # --------------------------------------------------------------
        for II in seq(0, (n - 2 + TI - 1) // TI):
            for JJ in seq(0, (n - 2 + TJ - 1) // TJ):
                for i_inner in seq(0, TI):
