                                    B[1 + II * TI + i_inner, 1 + JJ * TJ + j_inner]
                                    + B[1 + II * TI + i_inner, 1 + JJ * TJ + j_inner - 1]
                                    + B[1 + II * TI + i_inner, 1 + JJ * TJ + j_inner + 1]
                                    + B[1 + II * TI + i_inner + 1, 1 + JJ * TJ + j_inner]
                                    + B[1 + II * TI + i_inner - 1, 1 + JJ * TJ + j_inner]
                                )
