from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Spatial tile sizes. These are chosen to keep the working set of each
# tile (including vertical neighbors) in L1/L2 cache on a modern x64 CPU.
TI = 32  # tile size in i (rows)
TJ = 32  # tile size in j (cols)

@proc
def kernel_jacobi_2d(
    tsteps: size,
    n: size,
    A: DATA_TYPE[n, n] @ DRAM,
    B: DATA_TYPE[n, n] @ DRAM,
):
    # We update only interior points [1 : n-1), so n must be > 2.
    assert n > 2

    # Jacobi weight, kept in a register.
    w: DATA_TYPE
    w = 0.2

    # Time-stepping loop is strictly sequential because each step depends
    # on the result of the previous one.
    for t in seq(0, tsteps):

        # ------------------------------------------------------------------
        # Phase 1: update B from A using a 5-point stencil.
        # We tile the interior region [1, n-1) × [1, n-1) into TI×TJ blocks.
        # Each tile is processed in a cache-friendly way.
        # ------------------------------------------------------------------
        for ii in seq(0, (n - 2 + TI - 1) / TI):
            for jj in seq(0, (n - 2 + TJ - 1) / TJ):
                for i_inner in seq(0, TI):
                    for j_inner in seq(0, TJ):
                        # Global (i, j) coordinates of this point.
                        i_gl: index
                        j_gl: index
                        i_gl = 1 + ii * TI + i_inner
                        j_gl = 1 + jj * TJ + j_inner

                        # Guard to ensure we stay within the true interior:
                        #   1 <= i_gl <= n-2, 1 <= j_gl <= n-2
                        # This guarantees all neighbors used below are in-bounds.
                        if (i_gl < n - 1) and (j_gl < n - 1):
                            B[i_gl, j_gl] = w * (
                                A[i_gl,     j_gl    ] +
                                A[i_gl,     j_gl - 1] +
                                A[i_gl,     j_gl + 1] +
                                A[i_gl + 1, j_gl    ] +
                                A[i_gl - 1, j_gl    ]
                            )

        # ------------------------------------------------------------------
        # Phase 2: update A from B using the same 5-point stencil.
        # This phase starts only after Phase 1 has completed for all (i, j)
        # at this time step, preserving the Jacobi update semantics.
        # ------------------------------------------------------------------
        for ii in seq(0, (n - 2 + TI - 1) / TI):
            for jj in seq(0, (n - 2 + TJ - 1) / TJ):
                for i_inner in seq(0, TI):
                    for j_inner in seq(0, TJ):
                        i_gl: index
                        j_gl: index
                        i_gl = 1 + ii * TI + i_inner
                        j_gl = 1 + jj * TJ + j_inner

                        if (i_gl < n - 1) and (j_gl < n - 1):
                            A[i_gl, j_gl] = w * (
                                B[i_gl,     j_gl    ] +
                                B[i_gl,     j_gl - 1] +
                                B[i_gl,     j_gl + 1] +
                                B[i_gl + 1, j_gl    ] +
                                B[i_gl - 1, j_gl    ]
                            )

# ----------------------------------------------------------------------
# Scheduling directives
# ----------------------------------------------------------------------
# Mark the outer tile-row loops (ii) in both phases as parallelizable.
# Within a fixed time step and phase:
#   - Phase 1 writes disjoint regions of B while reading A (read-only).
#   - Phase 2 writes disjoint regions of A while reading B (read-only).
# Therefore each (ii, jj) tile is independent and can be run in parallel.

_kernel = kernel_jacobi_2d

# First ii loop: Phase 1 (B <- A).
ii_phase1 = _kernel.find_loop("ii")
_kernel = parallelize_loop(_kernel, ii_phase1)

# Second ii loop: Phase 2 (A <- B).
ii_phase2 = _kernel.find_loop("ii #1")
_kernel = parallelize_loop(_kernel, ii_phase2)

# Expose the scheduled kernel under the original name used by the C driver.
kernel_jacobi_2d = _kernel
EXO END
