from __future__ import annotations

from exo import *
from exo.API_scheduling import *  # imported as requested (no-op for this manually tiled kernel)
from exo.libs.memories import DRAM

# Tiling factors for the spatial dimensions.
# These are chosen to keep each tile's working set in L1/L2 cache while
# remaining large enough to amortize loop overhead. They can be tuned.
TI = 32  # tile size in i (rows)
TJ = 32  # tile size in j (columns)


@proc
def kernel_jacobi_2d(
    tsteps: size,
    n: size,
    A: DATA_TYPE[n, n] @ DRAM,
    B: DATA_TYPE[n, n] @ DRAM,
):
    # We update only interior points [1 : n-1), so n must be > 2.
    assert n > 2

    # Time loop: strictly sequential, as each step depends on the previous.
    for t in seq(0, tsteps):

        # ------------------------------------------------------------------
        # Phase 1: update B from A using a 5‑point stencil.
        #
        # This is the same computation as the original kernel:
        #
        #   for i in seq(1, n - 1):
        #       for j in seq(1, n - 1):
        #           B[i, j] = 0.2 * (
        #               A[i, j]
        #               + A[i, j - 1]
        #               + A[i, j + 1]
        #               + A[i + 1, j]
        #               + A[i - 1, j]
        #           )
        #
