        # interior region [1, n-1)×[1, n-1) into TI×TJ blocks and iterate over
        # tiles in (II, JJ), then points within each tile. Guards ensure that
        # we never touch the boundary or go out of bounds in the last (partial)
        # tiles.
        # ------------------------------------------------------------------
        for II in seq(0, (n - 2 + TI - 1) / TI):
            for JJ in seq(0, (n - 2 + TJ - 1) / TJ):
                for i in seq(0, TI):
                    ii: size
                    ii = 1 + II * TI + i
                    # Only process interior rows: 1 <= ii <= n-2
                    if ii < n - 1:
                        for j in seq(0, TJ):
                            jj: size
                            jj = 1 + JJ * TJ + j
                            # Only process interior columns: 1 <= jj <= n-2
                            if jj < n - 1:
                                B[ii, jj] = 0.2 * (
                                    A[ii, jj]
                                    + A[ii, jj - 1]
                                    + A[ii, jj + 1]
                                    + A[ii + 1, jj]
                                    + A[ii - 1, jj]
                                )

        # ------------------------------------------------------------------
        # Phase 2: update A from B using the same 5‑point stencil.
        #
        # Original (unoptimized) form:
        #
        #   for i in seq(1, n - 1):
        #       for j in seq(1, n - 1):
        #           A[i, j] = 0.2 * (
