        #               + B[i, j - 1]
        #               + B[i, j + 1]
        #               + B[i + 1, j]
        #               + B[i - 1, j]
        #           )
        #
        # We apply the same tiling pattern as Phase 1. Since Phase 1 completes
        # for all interior points before Phase 2 begins, every A update sees
        # exactly the same B values as in the original sequential version.
        # ------------------------------------------------------------------
        for II in seq(0, (n - 2 + TI - 1) / TI):
            for JJ in seq(0, (n - 2 + TJ - 1) / TJ):
